				 gcd = Gcd(x,n);
			}
		}

		System.out.println(gcd);

	}

	//最大公約数を求める
	public static int Gcd(int x, int y) {

		int n = Math.min(x, y);

		for (int i = n; i >= 1; i--) {
			if (x % i == 0 && y % i == 0) {
				return i;
			}
		}

		return 1;
	}
}

