    static class San {
        public int a, b, c;

        public San(int a, int b, int c) {
            int[] is = {a, b, c};
            Arrays.sort(is);
            this.a = is[0];
            this.b = is[1];
            this.c = is[2];
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            San san = (San) o;
            return a == san.a &&
                    b == san.b &&
                    c == san.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(a, b, c);
        }

        public int gcd() {
            int g = Main.gcd(a, b);
            g = Main.gcd(g, c);
            return g;
        }
    }

    public static final int gcd(final int a, final int b) {
        return (b == 0) ? a : gcd(b, a % b);
    }
