import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        long sum = 0;

        for(int a = 1; a <= k; a++)
        {
            for(int b = 1; b <= k; b++)
            {
                for(int c = 1; c <= k; c++)
                {
                    if(a == b && b ==c)
                    {
                        sum += a;
                    }
                    else
                    {
                        //最大公約数を求める
                        int buf = gcd(a,b,c);
                        sum += buf;
                    }
                }
            }
        }
        System.out.println(sum);
    }

    public static int gcd(int x,int y, int z) {
        if(x < y)
        {
            int buf = x;
            x = y;
            y = buf;
        }
        int r = 0;
        while(( r = x % y) != 0)
        {
            x = y;
            y = r;
        }

        if(y < z)
        {
            int buf = y;
            y = z;
            z = buf;
        }
        while((r = y % z) != 0)
        {
            y = z;
            z = r;
        }
        return z;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int K = scanner.nextInt();

        int num = 0;
        for (int i = 1; i < K + 1; i++) {
            for (int j = 1; j < K + 1; j++) {
                int cache = gcd(i, j);
                for (int k = 1; k < K + 1; k++) {
                    num += gcd(cache, k);
                }
            }
        }
        System.out.println(num);
    }

    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            a = a % b; // 残り部分
            return gcd(b, a); // 残り部分から最小の正方形を見つける
        }
    }
}

