            if (a[i] - a[i - 1] == 1) {
                System.out.println(0);
                return;
            }
        }
        long dp[] = new long[n + 2];
        dp[1] = 1;
        dp[2] = 1;
        for (int i = 3; i < n + 2; i++) {
            dp[i] = (dp[i - 1] + dp[i - 2]) % mod;
        }
        if (m == 0) {
            System.out.println(dp[n + 1]);
            return;
        }
