            for (Map.Entry<Integer, Integer> e : input.entrySet()) {
                if (e.getValue() <= limitedTime) {
                    ans = e.getKey();
                    break;
                }
            }

            if (ans == 0) {
                out.println("TLE");
                return;
            }

            out.println(ans);
        }

    }
}

