        int[][] input = new int[N][2];
        List<Integer> list = new ArrayList<>();

        for(int i = 0; i < N; i++){
            for(int j = 0; j < 2; j++){
                input[i][j] = sc.nextInt();
            }
        }
        for(int i = 0; i < N; i++) {
            if (input[i][1] <= timeLimit) {
                list.add(i);
            }
        }
