    static class ABC70 {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();
            if (c < a) {
                c ^= a;
                a ^= c;
                c ^= a;
                b ^= d;
                d ^= b;
                b ^= d;
            }
            if (b < c) {
                out.println("0");
                return;
            }
            int l = c;
            int r = Math.min(d, b);
            out.println(r - l);
