	    		time = B-C;
	    	}else {
	    		time = D-C;
	    	}
	    }else if( C<A && A<=D ){
	    	if( D<=B ) {
	    		time = D-A;
	    	}else {
	    		time = B-A;
	    	}
	    }

		System.out.println(time);
	}
}

